package e2e

// Tests that verify a project generated by crank can itself be operated
// on by crank. This is the highest-value end-to-end coverage: it proves
// the entire pipeline (init → go get → make → build → test) is self-
// consistent and the generated project plays well with the tool that
// produced it.
//
// The tests in this file use --project to target the generated project
// from outside (so we don't depend on PATH containing the crank binary),
// with two exceptions that simulate the user running `crank <cmd>` from
// inside the project (we add the crank binary to PATH for those).

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestE2E_Generated_VetFromOutside runs `crank vet --project=./myapp`
// against a generated project from a separate working directory.
// Verifies the binary works the same whether invoked from inside or
// outside the project.
func TestE2E_Generated_VetFromOutside(t *testing.T) {
	dir := scaffoldBase(t, "gen_vet")
	other := t.TempDir()
	runCrank(t, other, "vet", "--project", dir)
}

// TestE2E_Generated_BuildFromOutside: similar to above, but for build.
// The binary must produce a bin/<name> artifact.
func TestE2E_Generated_BuildFromOutside(t *testing.T) {
	dir := scaffoldBase(t, "gen_build")
	other := t.TempDir()
	runCrank(t, other, "build", "--project", dir)
	binary := filepath.Join(dir, "bin", filepath.Base(dir))
	if _, err := os.Stat(binary); err != nil {
		t.Errorf("expected build artifact at %s: %v", binary, err)
	}
}

// TestE2E_Generated_TestFromOutside: `crank test --project` runs the
