// TestE2E_Generated_ListFromOutside: `crank list` lists the features
// available to the (base) project. The command is global; it does not
// accept a --project flag.
func TestE2E_Generated_ListFromOutside(t *testing.T) {
	_ = scaffoldBase(t, "gen_list")
	other := t.TempDir()
	out := runCrank(t, other, "list")
	for _, f := range allFeatureNames {
		if !strings.Contains(out, f) {
			t.Errorf("list missing feature %q:\n%s", f, out)
		}
	}
}

