// TestE2E_Generated_ProjectManifestAccurate verifies the .crank.yaml
// accurately reflects the project state (project_name, module_path,
// features list, crank_version).
func TestE2E_Generated_ProjectManifestAccurate(t *testing.T) {
	dir := scaffoldBase(t, "gen_manifest")
	manifest := readFile(t, dir, ".crank.yaml")
	for _, want := range []string{
		"project_name: " + filepath.Base(dir),
		"module_path: github.com/example/" + filepath.Base(dir),
		"crank_version:",
		"- base",
	} {
		if !strings.Contains(manifest, want) {
			t.Errorf("manifest missing %q:\n%s", want, manifest)
		}
	}
}

// TestE2E_Generated_ProjectGoModAccurate verifies go.mod is consistent
// with the module_path in the manifest.
func TestE2E_Generated_ProjectGoModAccurate(t *testing.T) {
	dir := scaffoldBase(t, "gen_go_mod")
	gomod := readFile(t, dir, "go.mod")
	want := "module github.com/example/" + filepath.Base(dir)
	if !strings.HasPrefix(gomod, want) {
		t.Errorf("go.mod does not start with %q:\n%s", want, gomod)
	}
}

// TestE2E_Generated_ProjectMainImportsConfig verifies the main.go in
// cmd/server uses the project's module path to import the config package.
func TestE2E_Generated_ProjectMainImportsConfig(t *testing.T) {
	dir := scaffoldBase(t, "gen_main_imports")
	main := readFile(t, dir, "cmd/server/main.go")
	want := "github.com/example/" + filepath.Base(dir) + "/internal/config"
	if !strings.Contains(main, want) {
		t.Errorf("main.go missing import %q:\n%s", want, main)
	}
}

// TestE2E_Generated_FeatureCommandsCompose verifies the "compose and
// run" workflow: init → make scaffold → add feature → make scaffold →
// build. The whole thing must succeed end to end.
func TestE2E_Generated_FeatureCommandsCompose(t *testing.T) {
	dir := scaffold(t, "gen_compose", []string{"base", "gorm"})

	// Make a scaffold.
	runCrank(t, "", "make", "scaffold", "Customer", "name:string", "--project", dir)
	// Add another feature.
	runCrank(t, "", "add", "crypto", "--project", dir)
	// Make another scaffold.
	runCrank(t, "", "make", "scaffold", "Token", "value:string", "--project", dir)
	// Build the whole thing.
	runCrank(t, "", "build", "--project", dir)
	binary := filepath.Join(dir, "bin", filepath.Base(dir))
	if _, err := os.Stat(binary); err != nil {
		t.Errorf("expected build artifact at %s: %v", binary, err)
	}
}
